final_template:
AWSTemplateFormatVersion: "2010-09-09"
Description: "CloudFormation template to create an IoT Core policy for device onboarding using a Lambda-backed custom resource"
Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTDevicePolicyManagement
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:CreatePolicyVersion
                  - iot:SetDefaultPolicyVersion
                  - iot:ListPolicyVersions
                  - iot:DeletePolicyVersion
                  - iot:DeletePolicy
                  - iot:GetPolicy
                Resource: "*"
  CustomResourceLambda:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub "device-onboarding-custom-resource-${AWS::StackName}"
      Handler: index.handler
      Runtime: nodejs24.x
      Role: !GetAtt LambdaExecutionRole.Arn
      Timeout: 30
      Code:
        ZipFile: |
          const { IoTClient, CreatePolicyCommand, CreatePolicyVersionCommand, ListPolicyVersionsCommand, DeletePolicyVersionCommand, DeletePolicyCommand } = require("@aws-sdk/client-iot");
          const response = require('cfn-response');
          const client = new IoTClient({ region: process.env.AWS_REGION });

          exports.handler = async (event, context) => {
            console.log('Event:', JSON.stringify(event, null, 2));
            const physicalResourceId = event.PhysicalResourceId || `DevicePolicy-${event.ResourceProperties.StackName}`;
            const policyName = event.ResourceProperties.PolicyName || `DevicePolicy-${event.ResourceProperties.StackName}`;
            const policyDocument = event.ResourceProperties.PolicyDocument || JSON.stringify({
              Version: '2012-10-17',
              Statement: [
                { Effect: 'Allow', Action: 'iot:Connect', Resource: `arn:aws:iot:${process.env.AWS_REGION}:${event.ResourceProperties.AWSAccountId}:client/\${iot:Connection.Thing.ThingName}` },
                { Effect: 'Allow', Action: 'iot:Publish', Resource: `arn:aws:iot:${process.env.AWS_REGION}:${event.ResourceProperties.AWSAccountId}:topic/device/\${iot:Connection.Thing.ThingName}/*` },
                { Effect: 'Allow', Action: 'iot:Subscribe', Resource: `arn:aws:iot:${process.env.AWS_REGION}:${event.ResourceProperties.AWSAccountId}:topicfilter/device/\${iot:Connection.Thing.ThingName}/*` },
                { Effect: 'Allow', Action: 'iot:Receive', Resource: `arn:aws:iot:${process.env.AWS_REGION}:${event.ResourceProperties.AWSAccountId}:topic/device/\${iot:Connection.Thing.ThingName}/*` }
              ]
            });

            try {
              if (event.RequestType === 'Create') {
                console.log('Creating policy:', policyName);
                await client.send(new CreatePolicyCommand({ policyName, policyDocument }));
                await response.send(event, context, response.SUCCESS, { PolicyName: policyName }, policyName);
              } else if (event.RequestType === 'Update') {
                console.log('Updating policy:', physicalResourceId);
                const versions = await client.send(new ListPolicyVersionsCommand({ policyName: physicalResourceId }));
                for (const version of versions.policyVersions || []) {
                  if (!version.isDefaultVersion) {
                    await client.send(new DeletePolicyVersionCommand({ policyName: physicalResourceId, policyVersionId: version.versionId }));
                  }
                }
                await client.send(new CreatePolicyVersionCommand({ policyName: physicalResourceId, policyDocument, setAsDefault: true }));
                await response.send(event, context, response.SUCCESS, { PolicyName: physicalResourceId }, physicalResourceId);
              } else if (event.RequestType === 'Delete') {
                console.log('Deleting policy:', physicalResourceId);
                const versions = await client.send(new ListPolicyVersionsCommand({ policyName: physicalResourceId }));
                for (const version of versions.policyVersions || []) {
                  await client.send(new DeletePolicyVersionCommand({ policyName: physicalResourceId, policyVersionId: version.versionId }));
                }
                await client.send(new DeletePolicyCommand({ policyName: physicalResourceId }));
                await response.send(event, context, response.SUCCESS, {}, physicalResourceId);
              }
            } catch (err) {
              console.error('Error:', err);
              await response.send(event, context, response.FAILED, { Error: err.message }, physicalResourceId);
            }
          };
  DeviceOnboardingPolicy:
    Type: AWS::CloudFormation::CustomResource
    Properties:
      ServiceToken: !GetAtt CustomResourceLambda.Arn
      StackName: !Ref AWS::StackName
      AWSAccountId: !Ref AWS::AccountId
      PolicyName: !Sub "DevicePolicy-${AWS::StackName}"
      PolicyDocument: !Sub |
        {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Action": "iot:Connect",
              "Resource": "arn:aws:iot:${AWS::Region}:${AWS::AccountId}:client/${!iot:Connection.Thing.ThingName}"
            },
            {
              "Effect": "Allow",
              "Action": "iot:Publish",
              "Resource": "arn:aws:iot:${AWS::Region}:${AWS::AccountId}:topic/device/${!iot:Connection.Thing.ThingName}/*"
            },
            {
              "Effect": "Allow",
              "Action": "iot:Subscribe",
              "Resource": "arn:aws:iot:${AWS::Region}:${AWS::AccountId}:topicfilter/device/${!iot:Connection.Thing.ThingName}/*"
            },
            {
              "Effect": "Allow",
              "Action": "iot:Receive",
              "Resource": "arn:aws:iot:${AWS::Region}:${AWS::AccountId}:topic/device/${!iot:Connection.Thing.ThingName}/*"
            }
          ]
        }
Outputs:
  PolicyName:
    Description: "The name of the generated IoT Core policy for device onboarding"
    Value: !GetAtt DeviceOnboardingPolicy.PolicyName

AWSTemplateFormatVersion: "2010-09-09"
Description: "CloudFormation template for Amazon Verified Permissions policy store for a bookstore application with Cedar-based access control."
Parameters:
  AdminUserName:
    Type: String
    Default: "admin1"
    Description: "Name of the admin user to be explicitly forbidden from viewing books."
  SpecificUserName:
    Type: String
    Default: "specificUser"
    Description: "Name of the specific user permitted to view a specific book."
  SpecificBookName:
    Type: String
    Default: "specificBook"
    Description: "Name of the specific book that the specific user is permitted to view."
Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": ["Bookstore::Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": true
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "Bookstore::User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["Bookstore::User"],
                    "resourceTypes": ["Bookstore::Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["Bookstore::User"],
                    "resourceTypes": ["Bookstore::Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }
  PolicyAdminViewAnyBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal in Bookstore::Role::"Admin", action == Bookstore::Action::"View", resource)
            when { resource is Bookstore::Book };
  PolicyForbidAdminUser:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub |
            forbid(principal == Bookstore::User::"${AdminUserName}", action == Bookstore::Action::"View", resource)
            when { resource is Bookstore::Book };
  PolicyPublisherViewOwnBooks:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal in Bookstore::Role::"Publisher", action == Bookstore::Action::"View", resource)
            when { resource is Bookstore::Book && resource.owner == principal };
  PolicySpecificUserViewSpecificBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub |
            permit(principal == Bookstore::User::"${SpecificUserName}", action == Bookstore::Action::"View", resource == Bookstore::Book::"${SpecificBookName}");
  PolicyCustomerViewPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource)
            when { resource is Bookstore::Book && principal.yearsAsMember >= 2 };
  PolicyForbidCustomerViewPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource)
            when { resource is Bookstore::Book && principal.yearsAsMember < 2 };
  PolicyForbidNonUSRegion:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid(principal, action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"], resource)
            when { context.region != "US" };
  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: "Policy store ID for the bookstore application."
Outputs:
  PolicyStoreId:
    Description: "ID of the created policy store."
    Value: !Ref BookstorePolicyStore
  SSMParameterName:
    Description: "Name of the SSM parameter containing the policy store ID."
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: 'CloudFormation template for SimpleTodoAPI - A GraphQL API on AWS AppSync with DynamoDB backend using JavaScript resolvers'
Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: OwnerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      TableName: SimpleTodoTable
      Tags:
        - Key: Name
          Value: SimpleTodoTable
  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Scan
                  - dynamodb:Query
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/*"
      Tags:
        - Key: Name
          Value: AppSyncServiceRole
  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      Tags:
        - Key: Name
          Value: SimpleTodoAPI
  ApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |-
        type Todo {
          id: ID!
          title: String!
          description: String
          owner: String!
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }
        input CreateTodoInput {
          title: String!
          description: String
          owner: String!
        }
        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          owner: String
        }
        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }
        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          queryTodosByOwner(owner: String!): [Todo]
        }
        schema {
          query: Query
          mutation: Mutation
        }
  DynamoDBDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const { input } = ctx.arguments;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            id,
            title: input.title,
            description: input.description,
            owner: input.owner,
            createdAt: now,
            updatedAt: now,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }
        export function response(ctx) {
          return ctx.result;
        }
  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const { input } = ctx.arguments;
          const now = util.time.nowISO8601();
          const updates = [];
          const expressionNames = {};
          const expressionValues = {};
          if (input.title !== undefined) {
            updates.push('#title = :title');
            expressionNames['#title'] = 'title';
            expressionValues[':title'] = input.title;
          }
          if (input.description !== undefined) {
            updates.push('#description = :description');
            expressionNames['#description'] = 'description';
            expressionValues[':description'] = input.description;
          }
          if (input.owner !== undefined) {
            updates.push('#owner = :owner');
            expressionNames['#owner'] = 'owner';
            expressionValues[':owner'] = input.owner;
          }
          updates.push('#updatedAt = :updatedAt');
          expressionNames['#updatedAt'] = 'updatedAt';
          expressionValues[':updatedAt'] = now;
          const expression = 'SET ' + updates.join(', ');
          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
          };
        }
        export function response(ctx) {
          return ctx.result;
        }
  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const { id } = ctx.arguments;
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id }),
          };
        }
        export function response(ctx) {
          return ctx.result;
        }
  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const { id } = ctx.arguments;
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id }),
          };
        }
        export function response(ctx) {
          return ctx.result;
        }
  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }
        export function response(ctx) {
          return ctx.result.items;
        }
  QueryTodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: queryTodosByOwner
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const { owner } = ctx.arguments;
          return {
            operation: 'Query',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': owner }),
            },
            index: 'OwnerIndex',
          };
        }
        export function response(ctx) {
          return ctx.result.items;
        }
Outputs:
  GraphQLApiId:
    Description: 'API ID of the SimpleTodoAPI'
    Value: !GetAtt GraphQLApi.ApiId
  GraphQLApiEndpoint:
    Description: 'GraphQL endpoint URL for the SimpleTodoAPI'
    Value: !GetAtt GraphQLApi.GraphQLUrl
  ApiKey:
    Description: 'API Key for authenticating requests to the SimpleTodoAPI'
    Value: !GetAtt ApiKey.ApiKey
  DynamoDBTableName:
    Description: 'Name of the DynamoDB table backing the API'
    Value: !Ref TodoTable
